    }

    .primary {
      background: linear-gradient(180deg, var(--danger), var(--danger-strong));
      color: white;
      min-width: 118px;
    }

    @media (max-width: 780px) {
      .page {
        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
