     const closeButtons = dialog.querySelectorAll('.close, .secondary');
     const deleteButton = dialog.querySelector('.primary');

     trigger.addEventListener('click', () => {
       dialog.showModal();
     });

     closeButtons.forEach((button) => {
       button.addEventListener('click', () => dialog.close());
